INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('note_ojadjpdelzka', 'reader_y4wxhy4gj7da', 'Alder Page reading plan for cross-cultural teamwork — recorded by Alder Page Reader (@handledcfybkfbqm2a)', 'Our group of 8 met at Alder Page. We used paired reflection; the strongest prompt concerned cross-cultural teamwork. Next time we need an accessible entrance. Source circle: Alder Page Reader; publication time 2026-07-27T10:05:00+08:00.', 'Other', '["cross-cultural teamwork", "Alder Page", "team"]', '["Annotated page spread about cross-cultural teamwork", "Room layout at Alder Page"]', 7, 3, 1, 80, '2026-07-27T10:05:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('note_wpwnsy3mwvqa', 'reader_b4hoheodmnja', 'What our group learned from inclusive meetings — recorded by Inclusive Meetings Host (@handleutdi6bhmqpsa)', 'Our group of 9 met at Golden Spine. We used silent annotation; the strongest prompt concerned inclusive meetings. Next time we need an invoice before payment. Source circle: Inclusive Meetings Host; publication time 2026-07-26T17:17:00+08:00.', 'Study', '["inclusive meetings", "Cloud Shelf", "dinner"]', '["Annotated page spread about inclusive meetings", "Room layout at Golden Spine"]', 30, 20, 12, 177, '2026-07-26T17:17:00+08:00');
